#pragma once
#include "oldbox/common.hpp"

namespace oldbox {

// One PC/AT set-1 make code, optionally preceded by the E0 extended prefix.
// Break codes are generated by Keyboard::key_event().
struct Set1Key {
    u8 code = 0;
    bool extended = false;
};

// Translate an SDL_Scancode value (SDL3 stable numbering) to PC set 1.
// Returns {0, false} for keys that have no plain set-1 representation.
[[nodiscard]] Set1Key sdl_scancode_to_set1(int sdl_scancode);

} // namespace oldbox
